"""Compile verified HTTPS credentials and form submissions."""
from pathlib import Path
import argparse,hashlib,json,os,re,subprocess
from pmf_compiler import resolve_compiler

def build(compiler,out):
    root=Path(__file__).resolve().parents[1];out.mkdir(parents=True,exist_ok=False)
    cases=['basic','bad-password','bearer','form']
    names=['Anvil/Network/web_url.pbi','Anvil/Network/web_request.pbi','Anvil/Network/web_response.pbi','Anvil/Network/web_transport.pbi','Anvil/Network/web_client.pbi','Anvil/Network/web_credentials.pbi','Anvil/Network/web_form.pbi','RaspberryPi4/Lib/mmu.pi4']
    s='#WEB_KERNEL_BINDING=0\n'+'\n'.join('XIncludeFile "'+n+'"' for n in names)+'\nGlobal u.WebUrl\nGlobal q.WebRequest\nGlobal a.WebResponse\nGlobal client.WebClient\nGlobal form.WebForm\nGlobal Dim host.a[256]\nGlobal Dim target.a[1024]\nGlobal Dim qh.a[2048]\nGlobal Dim ah.a[4096]\nGlobal Dim line.a[1024]\nGlobal Dim tx.a[512]\nGlobal Dim rx.a[512]\nGlobal Dim output.a[64]\nGlobal Dim auth.a[256]\nGlobal Dim body.a[256]\nGlobal *wirePet,*wireTime\nGlobal wtable.i\nProcedure CaptureTable()\n ASM\n adrp x1, global_wtable\n add x1, x1, #:lo12:global_wtable\n str x0, [x1]\n EndASM\nEndProcedure\nProcedure.i Main()\n Define i.i,j.i,rc.i,start.i,n.i,v.i,p.i,off.i,total.i,take.i,step.i,length.i,k.i,method.i,methodLength.i\n CaptureTable()\n For i=0 To 32767 : PokeA($E1C00000+i,0) : Next\n PokeI($E1C00000,$57435632)\n rc=WebPayloadBind(wtable) : If rc<>0 : ProcedureReturn 1 : EndIf\n wirePet=PeekI(wtable+16+6*8) : wireTime=PeekI(wtable+16+11*8)\n MmuClearNc() : MmuAddNc($08A00000,$09200000) : MmuAddNc($08100000,$08180000)\n rc=MmuBuildTables($4F80000) : If rc<>0 : ProcedureReturn 2 : EndIf\n MmuEnableCached()\n For i=0 To 3\n  p=$E1C00100+i*4096 : total=0 : off=0 : length=0\n  u\\host=@host[0] : u\\hostCapacity=256 : u\\target=@target[0] : u\\targetCapacity=1024\n  method="GET" : methodLength=3\n  If i<2\n   v="https://httpbingo.org/basic-auth/anvil/demo"\n  ElseIf i=2\n   v="https://httpbingo.org/bearer"\n  Else\n   v="https://httpbingo.org/post" : method="POST" : methodLength=4\n   rc=WebFormInit(@form,"road",4,"Taylor St + 5th & Main",22,0)\n   While form\\phase<>4 And rc>=0\n    rc=WebFormOutput(@form,@body[total],7) : If rc>=0 : total=total+rc : EndIf\n   Wend\n  EndIf\n  n=0 : While PeekA(v+n)<>0 : n=n+1 : Wend\n  rc=WebUrlParse(v,n,1,@u)\n  If rc=0 : rc=WebRequestInit(@q,@u,method,methodLength,total,0,@qh[0],2048) : EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"User-Agent",10,"Anvil",5) : EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"Accept-Encoding",15,"identity",8) : EndIf\n  If i=0\n   n=WebCredentialBasic("anvil",5,"demo",4,@auth[0],256)\n  ElseIf i=1\n   n=WebCredentialBasic("anvil",5,"wrong",5,@auth[0],256)\n  ElseIf i=2\n   n=WebCredentialBearer("synthetic-test-token",20,@auth[0],256)\n  Else\n   n=0\n   If rc=0 : rc=WebRequestHeader(@q,"Content-Type",12,"application/x-www-form-urlencoded",33) : EndIf\n  EndIf\n  If n<0 : rc=n : ElseIf n>0 And rc=0 : rc=WebRequestHeader(@q,"Authorization",13,@auth[0],n) : EndIf\n  k=WebCredentialWipe(@auth[0],256)\n  If rc=0 : rc=WebRequestFinishHeaders(@q) : EndIf\n  If rc=0 : rc=WebResponseInit(@a,@line[0],1024,@ah[0],4096,0) : EndIf\n  start=wireTime()/1000\n  If rc=0 : rc=WebClientStart(@client,@u,@q,@a,@tx[0],512,@rx[0],512,start,20000) : EndIf\n  While rc=0\n   wirePet() : WebPayloadService(1)\n   take=total-off : If take>3 : take=3 : EndIf\n   step=WebClientStep(@client,@body[off],take,Bool(off+take=total),@output[0],31,wireTime()/1000)\n   off=off+client\\consumed : n=client\\written\n   If length+n>3072 : rc=-993 : Break : EndIf\n   For j=0 To n-1 : PokeA(p+64+length+j,output[j]) : Next\n   length=length+n\n   If step<>0 : rc=step : Break : EndIf\n  Wend\n  PokeI(p,rc) : PokeI(p+8,a\\status) : PokeI(p+16,wireTime()/1000-start) : PokeI(p+24,length) : PokeI(p+32,off) : PokeI(p+40,total)\n  WebClientClose(@client)\n  k=WebCredentialWipe(@qh[0],2048)\n  If rc<0 : Break : EndIf\n Next\n PokeI($E1C00008,rc)\n MmuDisableCachedFlushed() : ProcedureReturn 0\nEndProcedure\n'
    source=out/'proof.pi4';source.write_text(s,encoding='utf8')
    q=subprocess.run([str(resolve_compiler(compiler)),'--compile',str(source),'-t','pi4','--load-addr','0x1000000','--stack-addr','0x4f00000','--entry-returns','--wants-services','-o',str(out/'proof.img')],env=dict(os.environ,PMF_ROOT=str(root)),capture_output=True,text=True,encoding='utf8',timeout=180,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    log=q.stdout+q.stderr;(out/'compile.txt').write_text(log,encoding='utf8');print(log[-1800:]);assert q.returncode==0
    code=re.search(r'occupying \$([0-9A-Fa-f]+)\.\.\$([0-9A-Fa-f]+)',log);bss=re.search(r'bss \$([0-9A-Fa-f]+)\.\.\$([0-9A-Fa-f]+)',log)
    payload=(out/'proof.img.pmf').read_bytes();ranges={'code':['0x'+x for x in code.groups()],'bss':['0x'+x for x in bss.groups()],'stack':['0x4e00000','0x4efffff'],'report':['0xe1c00000','0xe1c07fff'],'tables':['0x4f80000','0x4f82fff']}
    (out/'identity.json').write_text(json.dumps(dict(bytes=len(payload),sha256=hashlib.sha256(payload).hexdigest(),checked_ranges=ranges,source_hashes={n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in names},cases=cases),indent=2),encoding='utf8')
if __name__=='__main__':
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--compiler',required=True);ap.add_argument('--out',type=Path,required=True)
    args=ap.parse_args();build(args.compiler,args.out.resolve())
